import{z as i,x as d,o as t,c as B,q as n,j as l,D as r,d as E,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"银行家算法","description":"","frontmatter":{"title":"银行家算法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/banker-algorithm.md","filePath":"cs/banker-algorithm.md","lastUpdated":1791063341000}'),p={name:"cs/banker-algorithm.md"};function m(c,a,h,C,D,f){const A=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=n('<h1 id="银行家算法" tabindex="-1">银行家算法 <a class="header-anchor" href="#银行家算法" aria-label="Permalink to &quot;银行家算法&quot;">​</a></h1><div class="epigraph"><p>只在分配之后仍存在安全序列时才把资源给出去；否则让请求者等待。</p><footer>—— 据 Dijkstra 对银行家算法的表述；Habermann, Prevention of System Deadlocks, CACM 1969 整理</footer></div><p><a href="/cs/deadlock-prevent">上一课</a>用四条件刻画死锁，预防常靠锁排序或一次性申请，对「先声明最大需求、再分次要」的系统太死。缺口是<strong>回避</strong>：每次分配都检查「即使所有人随后按最坏顺序要满配额，仍能找到做完的次序」。这就是银行家算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程声明最大需求向量，当前占用 + 仍可再要 ≤ 声明。系统有剩余向量。一次请求若立刻满足，剩余减少；若存在一个序列，使每个进程能在「剩余足够其仍需」时跑完并归还，则状态安全。缺口不是再列 Coffman 条件，而是这个安全检查。不安全不是已经死锁，而是存在走向死锁的路径。</p><p>本课不把多资源类型的矩阵代码写成可编译程序，只钉判据。</p><p><span class="marginnote">Dijkstra 把银行家比作：放贷后仍能应付所有客户按额度提现的某种次序。Habermann 把它接到操作系统资源管理。</span></p><p><span class="marginnote">常见误区：初学者容易把「不安全」当成「已经死锁」。实际不安全只是「存在走向死锁的可能」——进程也许声明了配额却根本不再要。银行家的代价正是这份保守：为了永不冒险，它可能挡住本来平安的请求。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对剩余 \\(A\\)、仍需矩阵 \\(Need\\)：反复找尚未完成且 \\(Need_i \\le A\\) 的进程，假想它跑完，\\(A\\) 加上它当前占用。若所有进程都能这样被点到，安全。分配前对试探后的状态跑同一检查，失败则阻塞请求。</p>',10)),(t(),l(o,null,{default:r(()=>[s(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20TRY%5B%22%E8%AF%95%E6%8E%A2%E5%88%86%E9%85%8D%22%5D%0A%20%20TRY%20--%3E%20SAFE%5B%22%E5%AD%98%E5%9C%A8%E5%AE%89%E5%85%A8%E5%BA%8F%E5%88%97%3F%22%5D%0A%20%20SAFE%20--%3E%20YES%5B%22%E7%9C%9F%E6%AD%A3%E7%BB%99%E8%B5%84%E6%BA%90%22%5D%0A%20%20SAFE%20--%3E%20NO%5B%22%E7%AD%89%E5%BE%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("回避比检测保守：拒绝进入不安全区，于是环不会形成。它要求"),e("strong",null,"事先知道最大需求"),E("，这在编译器已知的内核内部资源上偶尔成立，在用户随便 "),e("code",null,"malloc"),E(" 的世界里几乎不成立。因此通用 Unix 不以银行家为文件描述符的日常策略，教材用它说明「安全状态」与「死锁」不是同一集合。")],-1)),a[5]||(a[5]=e("p",null,[E("与"),e("a",{href:"/cs/scheduling-metrics"},"调度"),E("的关系：被银行家挡住的线程是阻塞，CPU 可以给别人；它等的是资源安全，不是 I/O 完成。")],-1)),(t(),l(o,null,{default:r(()=>[s(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22%E8%AF%95%E6%8E%A2%E5%90%8E%3A%20%E5%89%A9%E4%BD%99%20A%20%E4%B8%8E%E5%90%84%E8%BF%9B%E7%A8%8B%20Need%22%5D%20--%3E%20S1%7B%22%E8%BF%98%E6%9C%89%E6%9C%AA%E5%AE%8C%E6%88%90%E4%B8%94%20Need%20%E2%89%A4%20A%20%E7%9A%84%E8%BF%9B%E7%A8%8B%E5%90%97%3F%22%7D%0A%20%20S1%20--%3E%7C%22%E6%89%BE%E5%88%B0%20P%22%7C%20RUN%5B%22%E5%81%87%E6%83%B3%20P%20%E8%B7%91%E5%AE%8C%E5%B9%B6%E5%BD%92%E8%BF%98%E5%85%A8%E9%83%A8%E5%8D%A0%E7%94%A8%2C%20A%20%E5%A2%9E%E5%A4%A7%22%5D%0A%20%20RUN%20--%3E%20MARK%5B%22%E6%8A%8A%20P%20%E6%A0%87%E4%B8%BA%E5%AE%8C%E6%88%90%22%5D%20--%3E%20S1%0A%20%20S1%20--%3E%7C%22%E6%9C%89%E4%BA%BA%E6%B0%B8%E8%BF%9C%E5%87%91%E4%B8%8D%E9%BD%90%22%7C%20UNSAFE%5B%22%E6%97%A0%E5%AE%89%E5%85%A8%E5%BA%8F%E5%88%97%2C%20%E6%92%A4%E5%9B%9E%E8%AF%95%E6%8E%A2%22%5D%0A%20%20S1%20--%3E%7C%22%E5%85%A8%E9%83%A8%E6%A0%87%E5%AE%8C%22%7C%20SAFE%5B%22%E6%A0%87%E8%AE%B0%E6%AC%A1%E5%BA%8F%E5%8D%B3%E5%AE%89%E5%85%A8%E5%BA%8F%E5%88%97%2C%20%E5%88%86%E9%85%8D%E8%BD%AC%E6%AD%A3%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：库存 10，P1 占 3 需 5、P2 占 2 需 1、P3 占 2 需 6，剩余 3。按 P2→P1→P3 检查：给 P2 后收 2 得 5，给 P1 恰好收 3 得 8，P3 的 6 也够——安全。若先借 1 给 P3，剩余只剩 2，P1 的 5 永远凑不齐，试探失败，请求被拒。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不声称 Linux 内核用银行家分配页框。不把死锁检测（跑时找环）与回避混成一步。最大需求若说谎，安全证明作废。也不处理资源种类动态增减。</p><p>多实例资源用矩阵；单实例时安全检查退化为避免图中出现环的预演，仍要配额。</p><p><span class="marginnote">直觉类比：安全序列像停车场的挪车次序——你的车被围住不等于永远出不去；只要存在某个次序，轮到每辆车时它都挪得动，全场就不算堵死。银行家查的是「这个次序是否存在」，而不是「现在堵没堵」。</span></p><p>后课默认：四条件之外还有「安全序列」这条回避路。操作系统作为课程要从同步回到<strong>地址空间长什么样</strong>——下一课布局，页表硬件仍用<a href="/cs/paging-vm">分页</a>，不重导。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>安全 = 存在做完次序；银行家只进入安全状态。</li><li>不安全未必已死锁；需要事先配额。</li><li>通用 OS 很少对用户内存跑银行家；概念仍要。</li><li>出处：Dijkstra 银行家算法；Habermann, <em>CACM</em> 1969；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const S=i(p,[["render",m]]);export{P as __pageData,S as default};
